fn unicode_map(cp int, original string, keys []int, values []string) string {
    mut lo := 0
    mut hi := keys.len
    for lo < hi {
        mid := (lo + hi) / 2
        if cp < keys[mid] { hi = mid }
        else if cp > keys[mid] { lo = mid + 1 }
        else { return values[mid] }
    }
    return original
}

fn unicode_has_property(cp int, ranges []int) bool {
    mut lo := 0
    mut hi := ranges.len / 2
    for lo < hi {
        mid := (lo + hi) / 2
        if cp < ranges[mid * 2] { hi = mid }
        else if cp > ranges[mid * 2 + 1] { lo = mid + 1 }
        else { return true }
    }
    return false
}

fn codepoint_lower(s string) string { return unicode_map(unicode_point(s), s, unicode_lower_keys, unicode_lower_values) }
fn codepoint_upper(s string) string { return unicode_map(unicode_point(s), s, unicode_upper_keys, unicode_upper_values) }
fn codepoint_title(s string) string { return unicode_map(unicode_point(s), s, unicode_title_keys, unicode_title_values) }
fn codepoint_isalpha(s string) bool { return unicode_has_property(unicode_point(s), unicode_isalpha_ranges) }
fn codepoint_isalnum(s string) bool { return unicode_has_property(unicode_point(s), unicode_isalnum_ranges) }
fn codepoint_isdigit(s string) bool { return unicode_has_property(unicode_point(s), unicode_isdigit_ranges) }
fn codepoint_isspace(s string) bool { return unicode_has_property(unicode_point(s), unicode_isspace_ranges) }
fn codepoint_isupper(s string) bool { return unicode_has_property(unicode_point(s), unicode_isupper_ranges) }
fn codepoint_islower(s string) bool { return unicode_has_property(unicode_point(s), unicode_islower_ranges) }
fn codepoint_istitle(s string) bool { return unicode_has_property(unicode_point(s), unicode_istitle_ranges) }
